<?php
declare(strict_types=1);
require __DIR__ . '/app.php';
if (!installed()) redirect('install.php');
require_admin();
$section=(string)($_GET['section']??'dashboard');

if ($section==='export') {
    header('Content-Type: text/csv; charset=UTF-8');
    header('Content-Disposition: attachment; filename="bao-cao-tien-do-'.date('Y-m-d').'.csv"');
    $out=fopen('php://output','wb'); fwrite($out,"\xEF\xBB\xBF");
    fputcsv($out,['Họ tên','Email','Đơn vị','Khóa học','Số bài hoàn thành','Tổng số bài','Tỷ lệ (%)','Điểm tốt nhất','Hoạt động cuối']);
    $sql='SELECT u.full_name,u.email,u.unit_name,c.title,COUNT(DISTINCT CASE WHEN p.status="completed" THEN l.id END) done,COUNT(DISTINCT l.id) total,ROUND(COUNT(DISTINCT CASE WHEN p.status="completed" THEN l.id END)*100/NULLIF(COUNT(DISTINCT l.id),0),0) percent,MAX(p.best_score) best_score,MAX(p.updated_at) last_activity FROM users u CROSS JOIN courses c JOIN lessons l ON l.course_id=c.id AND l.status="published" LEFT JOIN progress p ON p.user_id=u.id AND p.lesson_id=l.id WHERE u.role="learner" GROUP BY u.id,c.id ORDER BY u.full_name,c.sort_order';
    foreach(db()->query($sql) as $r) fputcsv($out,array_map('csv_safe',$r)); audit_log('export_progress','report'); fclose($out); exit;
}

if ($_SERVER['REQUEST_METHOD']==='POST') {
    require_csrf(); $action=(string)($_POST['action']??'');
    try {
        if($action==='save_course'){
            $id=(int)($_POST['id']??0);$title=trim((string)$_POST['title']);$slug=trim((string)($_POST['slug']??''))?:slugify($title);
            $data=[$slug,$title,trim((string)($_POST['summary']??'')),json_encode(array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)($_POST['outcomes']??''))))),JSON_UNESCAPED_UNICODE),(int)($_POST['duration']??0),trim((string)($_POST['level']??'')),trim((string)($_POST['audience']??'all')),trim((string)($_POST['category']??'skills')),trim((string)($_POST['tone']??'blue')),trim((string)($_POST['label']??'')),($_POST['status']??'draft')==='published'?'published':'draft',(int)($_POST['sort_order']??0)];
            if($id){$st=db()->prepare('UPDATE courses SET slug=?,title=?,summary=?,outcomes=?,duration=?,level=?,audience=?,category=?,tone=?,label=?,status=?,sort_order=? WHERE id=?');$st->execute([...$data,$id]);}
            else{$st=db()->prepare('INSERT INTO courses(slug,title,summary,outcomes,duration,level,audience,category,tone,label,status,sort_order) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute($data);$id=(int)db()->lastInsertId();}
            if(array_key_exists('sources',$_POST)){$pdo=db();$pdo->prepare('DELETE FROM course_sources WHERE course_id=?')->execute([$id]);$add=$pdo->prepare('INSERT INTO course_sources(course_id,title,source_url,reviewed_at) VALUES(?,?,?,?)');foreach(preg_split('/\r\n|\r|\n/',(string)$_POST['sources']) as $line){$parts=array_map('trim',explode('|',$line,2));if(count($parts)===2&&filter_var($parts[1],FILTER_VALIDATE_URL))$add->execute([$id,$parts[0],$parts[1],date('Y-m-d')]);}}
            audit_log('save_course','course',$id,['title'=>$title]);
            flash('success','Đã lưu khóa học.');redirect('admin.php?section=course-edit&id='.$id);
        }
        if($action==='delete_course'){
            $id=(int)$_POST['id'];db()->prepare('DELETE FROM courses WHERE id=?')->execute([$id]);flash('success','Đã xóa khóa học và toàn bộ bài liên quan.');redirect('admin.php?section=courses');
        }
        if($action==='save_path'){
            $id=(int)($_POST['id']??0);$title=trim((string)$_POST['title']);$slug=trim((string)($_POST['slug']??''))?:slugify($title);$data=[$slug,$title,trim((string)$_POST['audience']),trim((string)$_POST['level']),trim((string)($_POST['summary']??'')),trim((string)($_POST['legal_basis']??'')),($_POST['status']??'draft')==='published'?'published':'draft',(int)($_POST['sort_order']??0)];$pdo=db();$pdo->beginTransaction();
            if($id){$pdo->prepare('UPDATE learning_paths SET slug=?,title=?,audience=?,level=?,summary=?,legal_basis=?,status=?,sort_order=? WHERE id=?')->execute([...$data,$id]);}else{$pdo->prepare('INSERT INTO learning_paths(slug,title,audience,level,summary,legal_basis,status,sort_order) VALUES(?,?,?,?,?,?,?,?)')->execute($data);$id=(int)$pdo->lastInsertId();}
            $pdo->prepare('DELETE FROM learning_path_courses WHERE path_id=?')->execute([$id]);$add=$pdo->prepare('INSERT INTO learning_path_courses(path_id,course_id,sort_order) VALUES(?,?,?)');foreach(array_values(array_unique(array_map('intval',(array)($_POST['course_ids']??[])))) as $i=>$courseId)if($courseId>0)$add->execute([$id,$courseId,$i+1]);$pdo->commit();audit_log('save_path','learning_path',$id,['title'=>$title]);flash('success','Đã lưu lộ trình.');redirect('admin.php?section=path-edit&id='.$id);
        }
        if($action==='delete_path'){$id=(int)$_POST['id'];db()->prepare('DELETE FROM learning_paths WHERE id=?')->execute([$id]);audit_log('delete_path','learning_path',$id);flash('success','Đã xóa lộ trình.');redirect('admin.php?section=paths');}
        if($action==='save_lesson'){
            $id=(int)($_POST['id']??0);$courseId=(int)$_POST['course_id'];
            $video=trim((string)($_POST['video_url']??''));if($video!==''&&!video_embed_url($video))throw new RuntimeException('Video chỉ chấp nhận liên kết YouTube hợp lệ.');
            $data=[$courseId,trim((string)$_POST['title']),trim((string)($_POST['objective']??'')),trim((string)($_POST['content']??'')),trim((string)($_POST['scenario']??'')),trim((string)($_POST['practice']??'')),$video,(int)($_POST['video_required_percent']??80),trim((string)($_POST['source_note']??'')),date('Y-m-d'),(int)($_POST['duration']??5),(int)($_POST['sort_order']??0),($_POST['status']??'draft')==='published'?'published':'draft'];
            if($id){$st=db()->prepare('UPDATE lessons SET course_id=?,title=?,objective=?,content=?,scenario=?,practice=?,video_url=?,video_required_percent=?,source_note=?,reviewed_at=?,duration=?,sort_order=?,status=? WHERE id=?');$st->execute([...$data,$id]);}
            else{$st=db()->prepare('INSERT INTO lessons(course_id,title,objective,content,scenario,practice,video_url,video_required_percent,source_note,reviewed_at,duration,sort_order,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)');$st->execute($data);$id=(int)db()->lastInsertId();}
            audit_log('save_lesson','lesson',$id,['course_id'=>$courseId]);
            flash('success','Đã lưu bài giảng.');redirect('admin.php?section=lesson-edit&id='.$id);
        }
        if($action==='delete_lesson'){$courseId=(int)$_POST['course_id'];db()->prepare('DELETE FROM lessons WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Đã xóa bài giảng.');redirect('admin.php?section=lessons&course_id='.$courseId);}
        if($action==='save_quiz'){
            $id=(int)($_POST['id']??0);$lessonId=(int)$_POST['lesson_id'];$question=trim((string)$_POST['question']);$explanation=trim((string)($_POST['explanation']??''));
            $options=array_values(array_filter(array_map('trim',(array)($_POST['options']??[])),fn($v)=>$v!==''));$correct=(int)($_POST['correct']??0);
            if(count($options)<2)throw new RuntimeException('Quiz cần ít nhất 2 phương án.'); if(!isset($options[$correct]))throw new RuntimeException('Vui lòng chọn đáp án đúng.');
            $pdo=db();$pdo->beginTransaction();
            if($id){$pdo->prepare('UPDATE quizzes SET question=?,explanation=? WHERE id=?')->execute([$question,$explanation,$id]);$pdo->prepare('DELETE FROM quiz_options WHERE quiz_id=?')->execute([$id]);}
            else{$pdo->prepare('INSERT INTO quizzes(lesson_id,question,explanation,sort_order) VALUES(?,?,?,?)')->execute([$lessonId,$question,$explanation,(int)($_POST['sort_order']??0)]);$id=(int)$pdo->lastInsertId();}
            $st=$pdo->prepare('INSERT INTO quiz_options(quiz_id,option_text,is_correct,sort_order) VALUES(?,?,?,?)');foreach($options as $i=>$option)$st->execute([$id,$option,$i===$correct?1:0,$i+1]);$pdo->commit();
            audit_log('save_quiz','quiz',$id,['lesson_id'=>$lessonId]);
            flash('success','Đã lưu câu hỏi quiz.');redirect('admin.php?section=quizzes&lesson_id='.$lessonId);
        }
        if($action==='delete_quiz'){$lessonId=(int)$_POST['lesson_id'];db()->prepare('DELETE FROM quizzes WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Đã xóa câu hỏi.');redirect('admin.php?section=quizzes&lesson_id='.$lessonId);}
        if($action==='save_user'){
            $id=(int)$_POST['id'];$role=($_POST['role']??'learner')==='admin'?'admin':'learner';$status=($_POST['status']??'active')==='locked'?'locked':'active';
            if($id===(int)user()['id']&&($role!=='admin'||$status!=='active'))throw new RuntimeException('Không thể tự thu hồi quyền quản trị hoặc khóa chính mình.');
            if($id){
                db()->prepare('UPDATE users SET full_name=?,unit_name=?,role=?,status=? WHERE id=?')->execute([trim((string)$_POST['full_name']),trim((string)($_POST['unit_name']??'')),$role,$status,$id]);
                if(!empty($_POST['password'])){if(strlen((string)$_POST['password'])<12)throw new RuntimeException('Mật khẩu mới phải có ít nhất 12 ký tự.');db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash((string)$_POST['password'],PASSWORD_DEFAULT),$id]);}
            }else{
                $email=mb_strtolower(trim((string)($_POST['email']??'')));$password=(string)($_POST['password']??'');
                if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Email không hợp lệ.');if(strlen($password)<12)throw new RuntimeException('Mật khẩu phải có ít nhất 12 ký tự.');
                db()->prepare('INSERT INTO users(email,password_hash,full_name,unit_name,role,status) VALUES(?,?,?,?,?,?)')->execute([$email,password_hash($password,PASSWORD_DEFAULT),trim((string)$_POST['full_name']),trim((string)($_POST['unit_name']??'')),$role,$status]);$id=(int)db()->lastInsertId();
            }
            audit_log('save_user','user',$id,['role'=>$role,'status'=>$status]);flash('success','Đã cập nhật tài khoản.');redirect('admin.php?section=users');
        }
        if($action==='delete_user'){$id=(int)$_POST['id'];if($id===(int)user()['id'])throw new RuntimeException('Không thể xóa tài khoản đang đăng nhập.');audit_log('delete_user','user',$id);db()->prepare('DELETE FROM users WHERE id=?')->execute([$id]);flash('success','Đã xóa tài khoản và dữ liệu tiến độ liên quan.');redirect('admin.php?section=users');}
        if($action==='save_settings'){
            $st=db()->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');
            foreach(['site_title','site_notice','allow_registration','allowed_email_domain','quiz_pass_score','privacy_retention_months'] as $key)$st->execute([$key,(string)($_POST[$key]??'')]);audit_log('save_settings','settings');flash('success','Đã lưu cấu hình.');redirect('admin.php?section=settings');
        }
    }catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();audit_log('admin_error','system',null,['type'=>get_class($e)]);flash('danger',$e instanceof PDOException?'Không thể lưu dữ liệu. Vui lòng kiểm tra lại hoặc xem nhật ký máy chủ.':$e->getMessage());redirect('admin.php?section='.$section.(!empty($_GET['id'])?'&id='.(int)$_GET['id']:''));}
}

function admin_start(string $title,string $active):void{
    page_header($title,true);$items=['dashboard'=>['Tổng quan','chart'],'courses'=>['Khóa học','book'],'paths'=>['Lộ trình','arrow'],'users'=>['Người dùng','user'],'reports'=>['Báo cáo','chart'],'audit'=>['Nhật ký','lock'],'settings'=>['Cấu hình','edit']];
    echo '<div class="admin-layout"><aside class="admin-side"><h2>Quản trị hệ thống</h2><nav>';foreach($items as $k=>$item)echo '<a class="'.($active===$k?'active':'').'" href="'.url('admin.php?section='.$k).'">'.icon($item[1]).e($item[0]).'</a>';echo '</nav><a class="admin-back" href="'.url('index.php').'">← Xem trang học</a></aside><main class="admin-main"><div class="admin-head"><div><p class="eyebrow">Bảng điều khiển</p><h1>'.e($title).'</h1></div></div>';
}
function admin_end():void{echo '</main></div>';page_footer();}
function confirm_button(string $action,int $id,string $label,array $extra=[]):string{$fields=csrf_field().'<input type="hidden" name="action" value="'.e($action).'"><input type="hidden" name="id" value="'.$id.'">';foreach($extra as $k=>$v)$fields.='<input type="hidden" name="'.e($k).'" value="'.e((string)$v).'">';return '<form method="post" class="inline" data-confirm="Hành động này không thể hoàn tác. Tiếp tục?">'.$fields.'<button class="btn-link danger" type="submit">'.e($label).'</button></form>';}

if($section==='dashboard'){
    admin_start('Tổng quan','dashboard');
    $stats=['Người học'=>(int)db()->query('SELECT COUNT(*) FROM users WHERE role="learner"')->fetchColumn(),'Khóa học'=>(int)db()->query('SELECT COUNT(*) FROM courses')->fetchColumn(),'Bài giảng'=>(int)db()->query('SELECT COUNT(*) FROM lessons')->fetchColumn(),'Lượt hoàn thành'=>(int)db()->query('SELECT COUNT(*) FROM progress WHERE status="completed"')->fetchColumn()];
    echo '<div class="stat-grid">';foreach($stats as $label=>$value)echo '<article><span>'.e($label).'</span><strong>'.number_format($value).'</strong></article>';echo '</div><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>Tiến độ theo khóa học</h2><a href="'.url('admin.php?section=reports').'">Xem báo cáo</a></div>';
    $rows=db()->query('SELECT c.title,COUNT(DISTINCT l.id) lessons,COUNT(DISTINCT p.user_id) learners,COUNT(CASE WHEN p.status="completed" THEN 1 END) completions FROM courses c LEFT JOIN lessons l ON l.course_id=c.id LEFT JOIN progress p ON p.lesson_id=l.id GROUP BY c.id ORDER BY completions DESC LIMIT 8')->fetchAll();
    foreach($rows as $r){$max=max(1,(int)$r['lessons']*max(1,(int)$r['learners']));$pct=min(100,(int)round((int)$r['completions']*100/$max));echo '<div class="metric-row"><div><strong>'.e($r['title']).'</strong><span>'.$r['learners'].' người học · '.$r['completions'].' lượt hoàn thành bài</span></div><div class="bar"><span style="width:'.$pct.'%"></span></div></div>';}
    echo '</section><section class="panel"><div class="panel-head"><h2>Hoạt động gần đây</h2></div>';
    $recent=db()->query('SELECT u.full_name,l.title,p.status,p.best_score,p.updated_at FROM progress p JOIN users u ON u.id=p.user_id JOIN lessons l ON l.id=p.lesson_id ORDER BY p.updated_at DESC LIMIT 10')->fetchAll();if(!$recent)echo '<div class="empty">Chưa có hoạt động học tập.</div>';foreach($recent as $r)echo '<div class="activity"><span>'.mb_substr($r['full_name'],0,1).'</span><div><strong>'.e($r['full_name']).'</strong><p>'.($r['status']==='completed'?'hoàn thành':'đã mở').' “'.e($r['title']).'” · '.e((string)$r['best_score']).' điểm</p></div><time>'.e(date('d/m H:i',strtotime($r['updated_at']))).'</time></div>';
    echo '</section></div>';admin_end();exit;
}

