    admin_start('Quản lý khóa học','courses');echo '<div class="actions"><a class="btn" href="'.url('admin.php?section=course-edit').'">+ Thêm khóa học</a></div><section class="panel table-wrap"><table><thead><tr><th>Khóa học</th><th>Trạng thái</th><th>Bài</th><th>Thứ tự</th><th></th></tr></thead><tbody>';
