if($section==='course-edit'){
    $id=(int)($_GET['id']??0);$c=['id'=>0,'slug'=>'','title'=>'','summary'=>'','outcomes'=>'[]','duration'=>20,'level'=>'Cơ bản','audience'=>'all','category'=>'skills','tone'=>'blue','label'=>'','status'=>'draft','sort_order'=>0];if($id){$st=db()->prepare('SELECT * FROM courses WHERE id=?');$st->execute([$id]);$c=$st->fetch()?:$c;}
