if($section==='lessons'){
    $courseId=(int)($_GET['course_id']??0);$st=db()->prepare('SELECT * FROM courses WHERE id=?');$st->execute([$courseId]);$course=$st->fetch();if(!$course){http_response_code(404);exit('Không tìm thấy khóa học.');}
