    $sql='SELECT u.id,u.full_name,u.email,u.unit_name,COUNT(DISTINCT p.lesson_id) started,COUNT(DISTINCT CASE WHEN p.status="completed" THEN p.lesson_id END) done,MAX(p.best_score) best_score,MAX(p.updated_at) last_activity FROM users u LEFT JOIN progress p ON p.user_id=u.id WHERE u.role="learner" GROUP BY u.id ORDER BY last_activity DESC,u.full_name';foreach(db()->query($sql) as $r)echo '<tr><td><strong>'.e($r['full_name']).'</strong><small>'.e($r['email']).'</small></td><td>'.e($r['unit_name']).'</td><td>'.$r['started'].' bài</td><td>'.$r['done'].' bài</td><td>'.($r['best_score']!==null?e((string)$r['best_score']).' điểm':'—').'</td><td>'.($r['last_activity']?date('d/m/Y H:i',strtotime($r['last_activity'])):'Chưa học').'</td></tr>';echo '</tbody></table></section>';admin_end();exit;
